import type { ClipDef } from './clips.ts';

/** Spoken lines of the curriculum lessons, as the content seed has them. See curriculum-lines.ts. */
export const CURRICULUM_CLIPS = [
  // ── iterated-dominance ──
  { id: "iterated-dominance.intro.heading", lesson: "iterated-dominance", character: "sen", style: "narration", sync: "computed", text: "Read the table like a detective. A payoff table lists what every combination of choices pays each player. Most of the work is ruling things out." },
  { id: "iterated-dominance.intro.line-1", lesson: "iterated-dominance", character: "meera", style: "dialogue", sync: "computed", text: "Before predicting what anyone does, find the moves nobody sensible would make." },
  { id: "iterated-dominance.intro.line-2", lesson: "iterated-dominance", character: "aarav", style: "dialogue", sync: "computed", text: "And once those are gone, the table gets smaller?" },
  { id: "iterated-dominance.concept.line", lesson: "iterated-dominance", character: "sen", style: "narration", sync: "computed", text: "An action is strictly dominated if another action pays more against every choice of the other side. Rational players never use it — and if everyone knows that, you can delete it and look again." },
  { id: "iterated-dominance.transfer.drop-9", lesson: "iterated-dominance", character: "sen", style: "narration", sync: "computed", text: "8 beats 9 against every rival choice, so 9 is dominated. You can drop it before thinking about the rival at all." },
  { id: "iterated-dominance.transfer.choose-8", lesson: "iterated-dominance", character: "sen", style: "narration", sync: "computed", text: "8 beats 9, but nothing here compares 8 with 7. Dominance rules options out; it doesn’t always pick the winner." },
  { id: "iterated-dominance.transfer.depends", lesson: "iterated-dominance", character: "sen", style: "narration", sync: "computed", text: "Some conclusions don’t depend on the rival: an option that loses against every rival choice can go." },
  { id: "iterated-dominance.done.takeaway", lesson: "iterated-dominance", character: "sen", style: "narration", sync: "computed", text: "Rule out what nobody would play, round by round. What survives is what you need to think about." },

  // ── best-response ──
  { id: "best-response.intro.heading", lesson: "best-response", character: "sen", style: "narration", sync: "computed", text: "What’s your best move — if you knew theirs? Most games have no dominant strategy. Your best choice depends on what the other side does, and theirs on yours." },
  { id: "best-response.intro.line-1", lesson: "best-response", character: "rohan", style: "dialogue", sync: "computed", text: "You can’t know where I’ll park. So how will you choose?" },
  { id: "best-response.intro.line-2", lesson: "best-response", character: "aarav", style: "dialogue", sync: "computed", text: "I can work out my best spot for each place he might go." },
  { id: "best-response.concept.line", lesson: "best-response", character: "sen", style: "narration", sync: "computed", text: "A Nash equilibrium is a set of choices in which each one is a best reply to the others. Nobody can do better by changing only their own choice." },
  { id: "best-response.transfer.stable", lesson: "best-response", character: "sen", style: "narration", sync: "computed", text: "Against loud music, loud is each one’s best reply, so neither changes alone. Both-quiet is also stable here — and better for both." },
  { id: "best-response.transfer.unstable", lesson: "best-response", character: "sen", style: "narration", sync: "computed", text: "Both preferring a different outcome doesn’t make this one unstable: getting there needs both to change at once." },
  { id: "best-response.transfer.unique", lesson: "best-response", character: "sen", style: "narration", sync: "computed", text: "It is stable, but not the only one: if both were quiet, neither would want to start playing loud." },
  { id: "best-response.done.takeaway", lesson: "best-response", character: "sen", style: "narration", sync: "computed", text: "Find each side’s best reply to the other. Where the replies meet, you have an outcome nobody will undo alone." },

  // ── market-competition ──
  { id: "market-competition.intro.heading", lesson: "market-competition", character: "sen", style: "narration", sync: "computed", text: "Every move changes your rival’s best move. In a market with few sellers, how much you make and what you charge change the price and the sales your rival faces." },
  { id: "market-competition.intro.line-1", lesson: "market-competition", character: "rohan", style: "dialogue", sync: "computed", text: "You make more, the price drops for both of us. You cut prices, I lose customers." },
  { id: "market-competition.intro.line-2", lesson: "market-competition", character: "meera", style: "dialogue", sync: "computed", text: "So the real question is how each of you responds to the other." },
  { id: "market-competition.concept.line", lesson: "market-competition", character: "sen", style: "narration", sync: "computed", text: "When firms choose quantities, each one’s best output falls as its rival produces more — and the market settles where both outputs are best replies to each other." },
  { id: "market-competition.transfer.respond", lesson: "market-competition", character: "sen", style: "narration", sync: "computed", text: "More capacity lowers the price both can charge; the rival’s best reply adjusts to it." },
  { id: "market-competition.transfer.same", lesson: "market-competition", character: "sen", style: "narration", sync: "computed", text: "The rival’s best reply depends on how much capacity is on the route." },
  { id: "market-competition.transfer.profit", lesson: "market-competition", character: "sen", style: "narration", sync: "computed", text: "Extra capacity pushes fares down for every bus, including the existing ones." },
  { id: "market-competition.done.takeaway", lesson: "market-competition", character: "sen", style: "narration", sync: "computed", text: "In a market of few rivals, plan your move around their best reply to it — and look for ways not to be identical." },

  // ── evolution ──
  { id: "evolution.intro.heading", lesson: "evolution", character: "sen", style: "narration", sync: "computed", text: "Nobody chooses. Strategies spread. Sometimes behaviour isn’t chosen in the moment: habits, conventions and instincts spread when they do well and fade when they don’t." },
  { id: "evolution.intro.line-1", lesson: "evolution", character: "meera", style: "dialogue", sync: "computed", text: "Instead of asking “what should I do?”, ask “which behaviours survive in a population?”" },
  { id: "evolution.intro.line-2", lesson: "evolution", character: "aarav", style: "dialogue", sync: "computed", text: "So the score depends on who else is out there." },
  { id: "evolution.concept.line", lesson: "evolution", character: "sen", style: "narration", sync: "computed", text: "A strategy — or mix — is evolutionarily stable if a small group doing something else earns less and fades away." },
  { id: "evolution.transfer.fade", lesson: "evolution", character: "sen", style: "narration", sync: "computed", text: "Like the rare Reciprocators, a small group mostly meets people on the old app. It needs a cluster above the tipping point." },
  { id: "evolution.transfer.win", lesson: "evolution", character: "sen", style: "narration", sync: "computed", text: "Being better when everyone uses it doesn’t help much when almost nobody does." },
  { id: "evolution.transfer.half", lesson: "evolution", character: "sen", style: "narration", sync: "computed", text: "When matching pays, mixed shares are unstable: the population tips one way." },
  { id: "evolution.done.takeaway", lesson: "evolution", character: "sen", style: "narration", sync: "computed", text: "What spreads is what earns more against the current mix. Stable mixes are the ones small invasions can’t break." },

  // ── sequential-moves ──
  { id: "sequential-moves.intro.heading", lesson: "sequential-moves", character: "sen", style: "narration", sync: "computed", text: "Think from the end. When moves happen in order and each player sees what came before, the right way to plan is backwards." },
  { id: "sequential-moves.intro.line-1", lesson: "sequential-moves", character: "meera", style: "dialogue", sync: "computed", text: "Draw the moves as a tree. Start at the last decision and ask what that player will do." },
  { id: "sequential-moves.intro.line-2", lesson: "sequential-moves", character: "aarav", style: "dialogue", sync: "computed", text: "Then the one before knows that, and so on back to me." },
  { id: "sequential-moves.concept.line", lesson: "sequential-moves", character: "sen", style: "narration", sync: "computed", text: "Solve the last decisions first, replace them by their outcomes, and work back to the start. The plan you get — what each player does at every point, even ones never reached — is a subgame-perfect equilibrium." },
  { id: "sequential-moves.transfer.outside", lesson: "sequential-moves", character: "sen", style: "narration", sync: "computed", text: "Working back from the buyer’s choice: they accept if your price is no worse than their alternative." },
  { id: "sequential-moves.transfer.cost", lesson: "sequential-moves", character: "sen", style: "narration", sync: "computed", text: "Your past cost doesn’t change what the buyer will accept." },
  { id: "sequential-moves.transfer.high", lesson: "sequential-moves", character: "sen", style: "narration", sync: "computed", text: "With bargaining that might work, but here the buyer only accepts or walks away." },
  { id: "sequential-moves.done.takeaway", lesson: "sequential-moves", character: "sen", style: "narration", sync: "computed", text: "When others respond to your move, solve their response first — then choose the move whose response you like best." },

  // ── credibility ──
  { id: "credibility.intro.heading", lesson: "credibility", character: "sen", style: "narration", sync: "computed", text: "Words are cheap. Threats and promises are about the future. Whether they work depends on what the speaker will want to do when the future arrives." },
  { id: "credibility.intro.line-1", lesson: "credibility", character: "rohan", style: "dialogue", sync: "computed", text: "Enter my market and you’ll regret it." },
  { id: "credibility.intro.line-2", lesson: "credibility", character: "aarav", style: "dialogue", sync: "computed", text: "Would he really hurt himself to hurt me?" },
  { id: "credibility.concept.line", lesson: "credibility", character: "sen", style: "narration", sync: "computed", text: "A threat is credible when carrying it out is the threatener’s best choice at that point. A commitment makes it credible by changing those later payoffs — or removing the option to back down." },
  { id: "credibility.transfer.weak", lesson: "credibility", character: "sen", style: "narration", sync: "computed", text: "When the moment comes, cancelling costs the threatener a lot. That makes it tempting to back down — which the teenager can anticipate." },
  { id: "credibility.transfer.strong", lesson: "credibility", character: "sen", style: "narration", sync: "computed", text: "Authority makes it possible, not attractive. Ask what the parent will prefer at the time." },
  { id: "credibility.transfer.reputation", lesson: "credibility", character: "sen", style: "narration", sync: "computed", text: "Reputation can matter in repeated settings — but this particular threat is costly to carry out, so it starts weak." },
  { id: "credibility.done.takeaway", lesson: "credibility", character: "sen", style: "narration", sync: "computed", text: "Believe threats that the other side would want to carry out. Make yours credible by changing what you’ll want to do later." },

  // ── bargaining ──
  { id: "bargaining.intro.heading", lesson: "bargaining", character: "sen", style: "narration", sync: "computed", text: "Who gets what? Bargaining divides a surplus. What each side gets depends less on fairness speeches and more on what happens if they say no." },
  { id: "bargaining.intro.line-1", lesson: "bargaining", character: "kavya", style: "dialogue", sync: "computed", text: "Offer me too little and I’ll walk — even if it costs me." },
  { id: "bargaining.intro.line-2", lesson: "bargaining", character: "meera", style: "dialogue", sync: "computed", text: "Then the question is whether walking away is credible, and what it costs." },
  { id: "bargaining.concept.line", lesson: "bargaining", character: "sen", style: "narration", sync: "computed", text: "Each side accepts any deal at least as good as what it gets by refusing. Change the cost of delay or the outside option, and the split changes with it." },
  { id: "bargaining.transfer.outside", lesson: "bargaining", character: "sen", style: "narration", sync: "computed", text: "Your outside option sets the minimum you accept — and the employer knows it." },
  { id: "bargaining.transfer.need", lesson: "bargaining", character: "sen", style: "narration", sync: "computed", text: "Needing it doesn’t raise what you can demand; if anything, it weakens your willingness to walk." },
  { id: "bargaining.transfer.fair", lesson: "bargaining", character: "sen", style: "narration", sync: "computed", text: "Fairness norms can matter in practice, but the credible alternative is what anchors the bargain." },
  { id: "bargaining.done.takeaway", lesson: "bargaining", character: "sen", style: "narration", sync: "computed", text: "In bargaining, power comes from what you can do if talks fail — your outside option, your patience, and your credibility in saying no." },

  // ── war-of-attrition ──
  { id: "war-of-attrition.intro.heading", lesson: "war-of-attrition", character: "sen", style: "narration", sync: "computed", text: "Who blinks first? Strikes, queues, lawsuits, price wars: sometimes nobody concedes, and both sides pay while they wait for the other to give up." },
  { id: "war-of-attrition.intro.line-1", lesson: "war-of-attrition", character: "rohan", style: "dialogue", sync: "computed", text: "I’ve been in this queue for four days. I’m not leaving now." },
  { id: "war-of-attrition.intro.line-2", lesson: "war-of-attrition", character: "meera", style: "dialogue", sync: "computed", text: "Those four days are gone either way. The question is tomorrow." },
  { id: "war-of-attrition.concept.line", lesson: "war-of-attrition", character: "sen", style: "narration", sync: "computed", text: "In a war of attrition both pay while waiting, and each hopes the other quits first. Decide by looking forward: is the chance of winning in the next round worth that round’s cost?" },
  { id: "war-of-attrition.transfer.forward", lesson: "war-of-attrition", character: "sen", style: "narration", sync: "computed", text: "Finishing is worth 1.5 million in expectation for 1 million: continue. The 2 million already spent shouldn’t enter the decision." },
  { id: "war-of-attrition.transfer.sunk", lesson: "war-of-attrition", character: "sen", style: "narration", sync: "computed", text: "The 2 million is spent either way. Letting it drive the decision is the sunk-cost fallacy." },
  { id: "war-of-attrition.transfer.total", lesson: "war-of-attrition", character: "sen", style: "narration", sync: "computed", text: "Close, but it mixes in the sunk 2 million and ignores the 70% chance of failure." },
  { id: "war-of-attrition.done.takeaway", lesson: "war-of-attrition", character: "sen", style: "narration", sync: "computed", text: "Persist only while the next round’s chance of winning is worth its cost. What you’ve already paid doesn’t count." },

  // ── repeated-cooperation ──
  { id: "repeated-cooperation.intro.heading", lesson: "repeated-cooperation", character: "sen", style: "narration", sync: "computed", text: "The shadow of the future. In Lesson 1, cooperation collapsed because there was no tomorrow. Most real relationships have one." },
  { id: "repeated-cooperation.intro.line-1", lesson: "repeated-cooperation", character: "arjun", style: "dialogue", sync: "computed", text: "If you cut corners on me this month, you lose my business next month." },
  { id: "repeated-cooperation.intro.line-2", lesson: "repeated-cooperation", character: "aarav", style: "dialogue", sync: "computed", text: "So today’s gain has to be weighed against all the months after." },
  { id: "repeated-cooperation.concept.line", lesson: "repeated-cooperation", character: "sen", style: "narration", sync: "computed", text: "If defecting today costs you cooperation tomorrow, and tomorrow is likely enough, cooperating can be in your own interest. That’s conditional cooperation — not trust, but incentives." },
  { id: "repeated-cooperation.transfer.cafe", lesson: "repeated-cooperation", character: "sen", style: "narration", sync: "computed", text: "Regulars make the future matter: one bad meal costs many future visits." },
  { id: "repeated-cooperation.transfer.tourist", lesson: "repeated-cooperation", character: "sen", style: "narration", sync: "computed", text: "Reviews do create a kind of future — reputation across customers — but each visitor’s own future visits don’t." },
  { id: "repeated-cooperation.transfer.same", lesson: "repeated-cooperation", character: "sen", style: "narration", sync: "computed", text: "The difference in repeat business changes the incentive to cut corners." },
  { id: "repeated-cooperation.done.takeaway", lesson: "repeated-cooperation", character: "sen", style: "narration", sync: "computed", text: "Cooperation can pay when today’s choice changes tomorrow’s treatment — if tomorrow is likely enough and cheating is seen in time." },

  // ── bayesian-uncertainty ──
  { id: "bayesian-uncertainty.intro.heading", lesson: "bayesian-uncertainty", character: "sen", style: "narration", sync: "computed", text: "You can’t see who they are. Competitors, suppliers and partners come in types — tough or soft, reliable or not — and only they know which." },
  { id: "bayesian-uncertainty.intro.line-1", lesson: "bayesian-uncertainty", character: "meera", style: "dialogue", sync: "computed", text: "You can’t see the type. But you can put a probability on it, and update it when evidence arrives." },
  { id: "bayesian-uncertainty.intro.line-2", lesson: "bayesian-uncertainty", character: "aarav", style: "dialogue", sync: "computed", text: "And decide on the average, weighted by those chances?" },
  { id: "bayesian-uncertainty.concept.line", lesson: "bayesian-uncertainty", character: "sen", style: "narration", sync: "computed", text: "Start with a prior. When evidence arrives, ask how likely it is under each possibility. The posterior weighs both — and decisions use the posterior." },
  { id: "bayesian-uncertainty.transfer.low", lesson: "bayesian-uncertainty", character: "sen", style: "narration", sync: "computed", text: "Of 1,000 people, about 1 true positive and about 10 false positives: roughly 1 in 11." },
  { id: "bayesian-uncertainty.transfer.99", lesson: "bayesian-uncertainty", character: "sen", style: "narration", sync: "computed", text: "99% is how often the test is right, not how often a positive is right. The rarity matters." },
  { id: "bayesian-uncertainty.transfer.ignore", lesson: "bayesian-uncertainty", character: "sen", style: "narration", sync: "computed", text: "The positive result raised the chance from 0.1% to about 9%. That’s worth following up." },
  { id: "bayesian-uncertainty.done.takeaway", lesson: "bayesian-uncertainty", character: "sen", style: "narration", sync: "computed", text: "Put probabilities on what you can’t see, update them with evidence, and decide on expected value — while remembering that big losses can matter more than their average." },

  // ── signaling ──
  { id: "signaling.intro.heading", lesson: "signaling", character: "sen", style: "narration", sync: "computed", text: "Show, don’t tell. Anyone can claim to be good. Some actions are only worth taking if you really are." },
  { id: "signaling.intro.line-1", lesson: "signaling", character: "kavya", style: "dialogue", sync: "computed", text: "Every seller says their product is great." },
  { id: "signaling.intro.line-2", lesson: "signaling", character: "meera", style: "dialogue", sync: "computed", text: "So look for what would be too costly for a bad seller to copy." },
  { id: "signaling.concept.line", lesson: "signaling", character: "sen", style: "narration", sync: "computed", text: "A signal separates types when it’s worth sending for one type and not for the other. Then the receiver can read it." },
  { id: "signaling.transfer.costly", lesson: "signaling", character: "sen", style: "narration", sync: "computed", text: "A founder who expected failure would lose more by investing personally. The cost differs by type." },
  { id: "signaling.transfer.money", lesson: "signaling", character: "sen", style: "narration", sync: "computed", text: "It does, but what investors want to learn is how good the company is." },
  { id: "signaling.transfer.always", lesson: "signaling", character: "sen", style: "narration", sync: "computed", text: "Not always: an over-optimistic founder might invest too. It’s informative, not proof." },
  { id: "signaling.done.takeaway", lesson: "signaling", character: "sen", style: "narration", sync: "computed", text: "Trust actions that would be too costly to fake — and as the uninformed side, design choices that make types reveal themselves." },

  // ── auctions ──
  { id: "auctions.intro.heading", lesson: "auctions", character: "sen", style: "narration", sync: "computed", text: "How much should you bid? Auctions look simple: highest bid wins. But the rules about what the winner pays change how you should bid." },
  { id: "auctions.intro.line-1", lesson: "auctions", character: "maya", style: "dialogue", sync: "computed", text: "I always bid exactly what something is worth to me." },
  { id: "auctions.intro.line-2", lesson: "auctions", character: "meera", style: "dialogue", sync: "computed", text: "Sometimes that’s perfect. Sometimes it guarantees you make nothing." },
  { id: "auctions.concept.line", lesson: "auctions", character: "sen", style: "narration", sync: "computed", text: "Pay-your-bid auctions reward shading. Second-price auctions make bidding your value weakly dominant — when values are private. When the value is common and uncertain, winning itself is bad news about your estimate." },
  { id: "auctions.transfer.curse", lesson: "auctions", character: "sen", style: "narration", sync: "computed", text: "The oil is worth the same to everyone. Winning by a lot means everyone else estimated less." },
  { id: "auctions.transfer.better", lesson: "auctions", character: "sen", style: "narration", sync: "computed", text: "Possible — but the default inference from winning a common-value auction is over-optimism." },
  { id: "auctions.transfer.bargain", lesson: "auctions", character: "sen", style: "narration", sync: "computed", text: "Winning by a wide margin is a warning sign, not evidence of a bargain." },
  { id: "auctions.done.takeaway", lesson: "auctions", character: "sen", style: "narration", sync: "computed", text: "Bid according to the rules and the kind of value: shade in first-price, bid your value in second-price private auctions, and correct for the winner’s curse when values are common." },

  // ── market-quality ──
  { id: "market-quality.intro.heading", lesson: "market-quality", character: "sen", style: "narration", sync: "computed", text: "When signals stop meaning anything. Lesson 16 showed how a signal can reveal quality. Here we follow what happens to a market when imitation and hidden quality take over." },
  { id: "market-quality.intro.line-1", lesson: "market-quality", character: "arjun", style: "dialogue", sync: "computed", text: "Buyers can’t tell good cars from bad. So they offer less. So the good cars leave." },
  { id: "market-quality.intro.line-2", lesson: "market-quality", character: "sen", style: "narration", sync: "computed", text: "And every step is individually rational." },
  { id: "market-quality.concept.line", lesson: "market-quality", character: "sen", style: "narration", sync: "computed", text: "When everyone does the same thing — sends the same signal, copies the same choice — observing them tells you nothing new. When quality is hidden, the price attracts the worst first." },
  { id: "market-quality.transfer.adverse", lesson: "market-quality", character: "sen", style: "narration", sync: "computed", text: "At an average price, healthy customers are overcharged and leave, raising the average cost — adverse selection." },
  { id: "market-quality.transfer.stable", lesson: "market-quality", character: "sen", style: "narration", sync: "computed", text: "The average changes as people decide whether to buy at that price." },
  { id: "market-quality.transfer.competition", lesson: "market-quality", character: "sen", style: "narration", sync: "computed", text: "Competition helps with prices, but every insurer faces the same hidden information." },
  { id: "market-quality.done.takeaway", lesson: "market-quality", character: "sen", style: "narration", sync: "computed", text: "Signals lose meaning when they’re cheap to imitate, crowds lose information when they copy, and markets shrink when only the informed can see quality." },

  // ── coalitions ──
  { id: "coalitions.intro.heading", lesson: "coalitions", character: "sen", style: "narration", sync: "computed", text: "Who teams up with whom? Groups create value together — and then have to divide it. Any subgroup that can do better on its own may walk away." },
  { id: "coalitions.intro.line-1", lesson: "coalitions", character: "nina", style: "dialogue", sync: "computed", text: "We all agreed on the split. Done!" },
  { id: "coalitions.intro.line-2", lesson: "coalitions", character: "meera", style: "dialogue", sync: "computed", text: "Agreed today. Is there a pair who could do better without the rest?" },
  { id: "coalitions.concept.line", lesson: "coalitions", character: "sen", style: "narration", sync: "computed", text: "A coalition blocks a deal if it could earn more on its own than the deal gives its members. Deals no coalition can block form the core." },
  { id: "coalitions.transfer.unsafe", lesson: "coalitions", character: "sen", style: "narration", sync: "computed", text: "That pair is a blocking coalition. A stable arrangement must charge every pair no more than going alone." },
  { id: "coalitions.transfer.safe", lesson: "coalitions", character: "sen", style: "narration", sync: "computed", text: "Signing shows agreement, not stability. When the contract ends, a pair can leave." },
  { id: "coalitions.transfer.equal", lesson: "coalitions", character: "sen", style: "narration", sync: "computed", text: "Equal shares can still leave some pair paying more than its own system would cost." },
  { id: "coalitions.done.takeaway", lesson: "coalitions", character: "sen", style: "narration", sync: "computed", text: "Test a deal against every group that could leave together. If some group can always do better, no deal is stable." },

  // ── voting ──
  { id: "voting.intro.heading", lesson: "voting", character: "sen", style: "narration", sync: "computed", text: "The rules pick the winner. Same voters, same preferences — different voting rules or a different order of votes can produce a different result." },
  { id: "voting.intro.line-1", lesson: "voting", character: "arjun", style: "dialogue", sync: "computed", text: "If I vote for my favourite, I might help my least favourite win." },
  { id: "voting.intro.line-2", lesson: "voting", character: "sen", style: "narration", sync: "computed", text: "Then your vote and your preference can come apart." },
  { id: "voting.concept.line", lesson: "voting", character: "sen", style: "narration", sync: "computed", text: "When majorities cycle — A beats B, B beats C, C beats A — no option beats all others, and whoever sets the order of votes can steer the result." },
  { id: "voting.transfer.last", lesson: "voting", character: "sen", style: "narration", sync: "computed", text: "With cyclic majorities, the option kept to the end and pitted against the one it beats wins." },
  { id: "voting.transfer.first", lesson: "voting", character: "sen", style: "narration", sync: "computed", text: "Entering early means the city must beat two options in a row — which a cycle rules out." },
  { id: "voting.transfer.none", lesson: "voting", character: "sen", style: "narration", sync: "computed", text: "With cyclic majorities, order is exactly what decides." },
  { id: "voting.done.takeaway", lesson: "voting", character: "sen", style: "narration", sync: "computed", text: "Ask what your vote changes, check whether majorities cycle, and watch who controls the procedure." },

  // ── brinkmanship ──
  { id: "brinkmanship.intro.heading", lesson: "brinkmanship", character: "sen", style: "narration", sync: "computed", text: "Going to the edge. Some conflicts are won by being willing to create risk — a danger neither side fully controls." },
  { id: "brinkmanship.intro.line-1", lesson: "brinkmanship", character: "maya", style: "dialogue", sync: "computed", text: "If I make the situation dangerous enough, you’ll back down first." },
  { id: "brinkmanship.intro.line-2", lesson: "brinkmanship", character: "aarav", style: "dialogue", sync: "computed", text: "Unless the danger gets us both." },
  { id: "brinkmanship.concept.line", lesson: "brinkmanship", character: "sen", style: "narration", sync: "computed", text: "Brinkmanship is a threat that leaves something to chance: you can’t promise a disaster, but you can raise its probability — and that pressures the other side." },
  { id: "brinkmanship.transfer.brink", lesson: "brinkmanship", character: "sen", style: "narration", sync: "computed", text: "Neither controls the judge. Each motion raises the chance of a result both dislike." },
  { id: "brinkmanship.transfer.attrition", lesson: "brinkmanship", character: "sen", style: "narration", sync: "computed", text: "There’s waiting and cost, but the key feature is the rising risk they create." },
  { id: "brinkmanship.transfer.credible", lesson: "brinkmanship", character: "sen", style: "narration", sync: "computed", text: "The bad outcome isn’t chosen by either firm — it’s left to chance." },
  { id: "brinkmanship.done.takeaway", lesson: "brinkmanship", character: "sen", style: "narration", sync: "computed", text: "Risk shared on purpose can force concessions — but only up to the point where the danger you add outweighs the pressure you gain." },

  // ── strategic-practice ──
  { id: "strategic-practice.intro.heading", lesson: "strategic-practice", character: "sen", style: "narration", sync: "computed", text: "No labels this time. Real situations don’t say “this is a Prisoner’s Dilemma”. This lesson practises the step that comes first: working out what kind of situation you’re in." },
  { id: "strategic-practice.intro.line-1", lesson: "strategic-practice", character: "sen", style: "narration", sync: "computed", text: "Who are the players? What can they do? Who knows what, and who moves when? Answer those, and the model usually follows." },
  { id: "strategic-practice.intro.line-2", lesson: "strategic-practice", character: "aarav", style: "dialogue", sync: "computed", text: "Then I pick the tool, not the other way round." },
  { id: "strategic-practice.concept.line", lesson: "strategic-practice", character: "sen", style: "narration", sync: "computed", text: "Players and goals. Actions. Information. Timing. Uncertainty and incentives. Model. Prediction. And what would change your mind." },
  { id: "strategic-practice.transfer.timing", lesson: "strategic-practice", character: "sen", style: "narration", sync: "computed", text: "Timing and visibility decide whether this is a race, a sequential game or a coordination problem." },
  { id: "strategic-practice.transfer.fair", lesson: "strategic-practice", character: "sen", style: "narration", sync: "computed", text: "That’s a question about fairness; it doesn’t tell you what will happen." },
  { id: "strategic-practice.transfer.payoff", lesson: "strategic-practice", character: "sen", style: "narration", sync: "computed", text: "Payoffs matter — but without timing and information you can’t choose the model." },
  { id: "strategic-practice.done.takeaway", lesson: "strategic-practice", character: "sen", style: "narration", sync: "computed", text: "Start with players, actions, information and timing. Then choose the model, predict, decide — and say what would change your mind." },
] as const satisfies readonly ClipDef[];
